mapper.select:
select PROD_REGIST_NO prodRegistNo, DATA_STATUS dataStatus, NOCREATE_REASON nocreateReason, REPORT_ISSUE_DATE reportIssueDate, IS_SALES_AGENCY isSalesAgency, DATA_SOURCE, UPDATE_TIME updateTime, UPDATE_USER updateUser from DIS_PROD_NOCREATE
AND PROD_REGIST_NO in
#{item}
AND PROD_ID in
#{item}
AND DATA_STATUS=#{dataStatus}
AND REPORT_ISSUE_DATE >= TO_DATE(#{reportIssueDateStart},'YYYY-MM-DD')
AND REPORT_ISSUE_DATE <= TO_DATE(#{reportIssueDateEnd},'YYYY-MM-DD')

select PROD_RE
from REP_PROD_INFO
where PROD_RE = #{prodRegistNo,jdbcType=VARCHAR}
